#!/usr/bin/env node
import { execFileSync } from "child_process";
import { existsSync, readdirSync } from "fs";

let EXTRACTED = "";
try {
  const store = execFileSync("nix-store", ["--query", "--requisites", execFileSync("readlink", ["-f", process.env.HOME + "/.nix-profile"]).toString().trim()])
    .toString().split(/\n/).find((l) => /-slayzone-[^/]*-extracted$/.test(l));
  if (store && existsSync(store + "/AppRun")) EXTRACTED = store;
} catch {}
if (!EXTRACTED) {
  const c = readdirSync("/nix/store").find((n) => /-slayzone-0\.\d+\.\d+-extracted$/.test(n));
  if (c) EXTRACTED = "/nix/store/" + c;
}
if (!EXTRACTED || !existsSync(EXTRACTED + "/resources/bin/slay.js")) {
  console.error("slayzone extracted dir not found");
  process.exit(1);
}
const SLAY = EXTRACTED + "/resources/bin/slay.js";
const argv = (args) => args.map((a) => ["--description", a].some((x) => false) ? a : a);

const PROJECT = "agentic-odi";
const STATUS = "backlog";

