console.log(`Validated ${issues.length} issues. Creating…`);

// Build a human-readable description: summary + acceptance + files + effort + prompt.
const buildDesc = (i) =>
  `## Why\n${i.description}\n\n` +
  `## Acceptance\n${i.acceptance}\n\n` +
  `## Files\n${i.files}\n\n` +
  `## Effort\n${i.effort}\n\n` +
  `## Prompt for implementer\n${i.prompt}`.replace(/\$/g, "$$$$"); // escape $ for shell

let created = 0;
for (const issue of issues) {
  const desc = buildDesc(issue);
  // Pass via argv; each arg is a single argv string (no shell joining needed with execFileSync).
  try {
    const out = execFileSync("node", ["--no-warnings", SLAY, "tasks", "create",
      "--status", STATUS, "--project", PROJECT, "--description", desc, issue.title],
      { stdio: ["ignore", "pipe", "pipe"], timeout: 25000 });
    process.stdout.write(out);
    created++;
  } catch (e) {
    const msg = (e.stderr ? e.stderr.toString() : "") + (e.message ? e.message : "");
    console.error(`FAIL ${issue.title.slice(0,60)} :: ${msg.slice(0,240)}`);
  }
}
console.log(`\nCreated ${created}/${issues.length}`);

