#!/usr/bin/env node
import { execFileSync } from "child_process";
import { existsSync } from "fs";

// resolve SLAY
let EXTRACTED = "";
try {
  const pf = execFileSync("readlink", ["-f", process.env.HOME + "/.nix-profile"]).toString().trim();
  const reqs = execFileSync("nix-store", ["--query", "--requisites", pf]).toString().split(/\n/);
  const m = reqs.find((l) => /-slayzone-[^/]*-extracted$/.test(l));
  if (m && existsSync(m + "/AppRun")) EXTRACTED = m;
} catch {}
if (!EXTRACTED) {
  const fs = require("fs");
  const c = fs.readdirSync("/nix/store").find((n) => /-slayzone-0\.\d+\.\d+-extracted$/.test(n));
  EXTRACTED = c ? "/nix/store/" + c : "";
}
const SLAY = EXTRACTED + "/resources/bin/slay.js";
if (!existsSync(SLAY)) { console.error("slay.js missing"); process.exit(1); }

const THEME = {
  "57c8f8cc":"docs-truth","643f97e1":"studio-joy","0b418bca":"studio-joy","a71f9ef8":"studio-joy",
  "3b0876d3":"studio-joy","4f26db54":"catch-up","9ac9adde":"studio-joy","5e5455fa":"studio-joy",
  "8150a65c":"studio-joy","5d05845d":"studio-joy","4e2d25a5":"studio-joy","5e3f6628":"studio-joy",
  "db270c1f":"studio-joy","905c2fb9":"studio-joy","40801363":"trust-data","a919b8a6":"trust-data",
  "99d6e5ef":"trust-data","1429fb91":"cli-robust","9b1399d4":"cli-robust","ffeaac48":"cli-robust",
  "da3ff8e5":"reliability","f4fc1fa2":"reliability","2d9a8843":"ship-reliable","3627e660":"cli-robust",
  "c4ff4f19":"cli-robust","c2430966":"cli-robust","6538dc1a":"parity","3eee5ac7":"ship-reliable",
  "b96f3017":"ship-reliable","e4060c02":"ship-reliable","2b82623d":"docs-truth","62a666c0":"docs-truth",
  "949445bc":"docs-truth","a75d6c9c":"docs-site","edc09bed":"docs-site","6f843cd0":"docs-site",
  "aa1f2ae9":"docs-site","2af8088e":"docs-site","f700e813":"ship-reliable","22f882f2":"docs-truth",
  "466e0812":"parity","c557d9a1":"tests","82186712":"tests","0977b0c9":"tests","39db1f2d":"tests",
  "c8480d05":"tests","bf6dd851":"tests","bb009786":"tests","b737e2cf":"studio-joy","f9c586e5":"studio-joy",
  "33d66ae8":"catch-up","ab9f5d28":"docs-truth",
};

const live = JSON.parse(execFileSync("node", ["--no-warnings", SLAY, "tasks", "list", "--status", "backlog", "--limit", "500", "--json"], { timeout: 20000 }).toString());
const liveById = new Set(live.map((t) => t.id.slice(0, 8)));

let done = 0, skip = 0;
for (const [prefix, theme] of Object.entries(THEME)) {
  if (!liveById.has(prefix)) { skip++; continue; }
  try {
    execFileSync("node", ["--no-warnings", SLAY, "tasks", "tag", prefix, "--add", "theme:" + theme],
      { stdio: ["ignore","pipe","pipe"], timeout: 20000 });
    process.stdout.write(`OK  ${prefix}  theme:${theme}\n`);
    done++;
  } catch (e) {
    console.error(`FAIL ${prefix} theme:${theme} :: ${(e.stderr?e.stderr.toString():"")}${e.message?" "+e.message:""}`.slice(0,200));
  }
}
console.log(`\nTagged ${done}/${Object.keys(THEME).length} (skipped ${skip} that left backlog)`);

